  // E6/src/demo.js
  var VGS_DEMO = [3.5, 4, 4.5];
  var PIEZA_DEMO = { id: "demostracion", vth: 1.8, ron: 1.85 };
  var VDS_MAX = 2.5;
  var N = 24;
  var T_PREP = 1.6;
  var T_BARRIDO = 9;
  var T_SOSTEN = 5;
  var T_REPOSO = 1.6;
  var CICLO = T_PREP + T_BARRIDO + T_SOSTEN + T_REPOSO;
  var INICIO_DEMO = T_PREP + 0.9 * T_BARRIDO;
  function crearDemo() {
    const cfg = { ...cfgEstandar(), ideal: true }, banco = { id: "DEMOSTRACION", err: { dT1: 0, dT2: 0 } };
    const pieza = { id: PIEZA_DEMO.id, Q: piezaMos(PIEZA_DEMO.vth, PIEZA_DEMO.ron) };
    const fam = curvasMos(banco, cfg, pieza, VGS_DEMO, VDS_MAX, N);
    const D = cfg.ancho / cfg.periodo, Trec = cfg.Tset, kc = D * (HOJA_MOS.RTHJA - RTHJC_HIP);
    let Imax = 0;
    for (const s of fam) for (const p of s.pts) Imax = Math.max(Imax, p.y);
    const puntos = [];
    fam.forEach((s, k) => s.pts.forEach((p, i) => puntos.push({ k, i, n: s.pts.length, x: p.x / VDS_MAX, y: p.y / Imax, tj: p.Tj_C, tc: Trec + p.x * p.y * kc, limite: p.limite })));
    const real = puntos.length * cfg.periodo;
    return {
      puntos,
      Trec,
      curvas: fam.length,
      factor: real / T_BARRIDO,
      real,
      /** Estado de la demostración a los `t` segundos de pantalla desde que empezó (cíclico). */
      estado(t) {
        const tc = (t % CICLO + CICLO) % CICLO;
        if (tc < T_PREP) return { fase: "prep", k: -1, prog: 0, punto: null, t: tc };
        if (tc < T_PREP + T_BARRIDO) {
          const u = (tc - T_PREP) / T_BARRIDO, j = Math.min(puntos.length - 1, Math.floor(u * puntos.length));
          return { fase: "barrido", k: j, prog: u, punto: puntos[j], t: tc };
        }
        if (tc < T_PREP + T_BARRIDO + T_SOSTEN) return { fase: "sosten", k: puntos.length - 1, prog: 1, punto: puntos[puntos.length - 1], t: tc };
        return { fase: "reposo", k: puntos.length - 1, prog: 1, punto: null, tReposo: tc - T_PREP - T_BARRIDO - T_SOSTEN, t: tc };
      },
      /** Lo único que el dock enseña de la demostración (sin corriente, tensión ni potencia): Tj ilustrativa entera, estado
       *  de la SMU y canal activo. */
      dock(t) {
        const e = this.estado(t), on = e.fase === "barrido" || e.fase === "sosten";
        return { t: e.t, fase: e.fase, tj: Math.round(e.punto ? e.punto.tj : Trec), salida: on, canal: on ? "A y B" : "ninguno" };
      }
    };
  }

  // E6/src/escena.js
  var YB = 0.9;
  var FOV = 27;
